CREATE TABLE jobs(id UUID PRIMARY KEY,business_id UUID,created_by_user_id UUID NOT NULL,title VARCHAR(200) NOT NULL,location VARCHAR(150),contract_type VARCHAR(80),description TEXT,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE TABLE applications(id UUID PRIMARY KEY,job_id UUID NOT NULL REFERENCES jobs(id),candidate_id UUID NOT NULL,candidate_cv_id UUID NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(job_id,candidate_id));